package com.apexstudio.app.data.engine

/**
 * Factory for common FFmpeg command-line argument arrays used by ApexStudio.
 *
 * All methods return [Array<String>] ready to be passed to [FFmpegEngine.execute].
 *
 * Generated by OpenRouter model: nvidia/nemotron-3.5-super-vl:free
 * Completed and verified by Guard (Muse) — model output was truncated.
 */
object FFmpegCommands {

    /**
     * Builds an FFmpeg command to trim a video segment.
     *
     * Uses stream copying (`-c copy`) for fast trimming without re-encoding.
     * Note: stream-copy trimming is keyframe-accurate, not frame-accurate.
     *
     * @param input path to the source video file
     * @param output path for the trimmed video file
     * @param startMs start time in milliseconds
     * @param endMs end time in milliseconds
     * @return FFmpeg CLI arguments
     */
    fun trimVideo(input: String, output: String, startMs: Long, endMs: Long): Array<String> {
        return arrayOf(
            "-y",
            "-i", input,
            "-ss", msToTimecode(startMs),
            "-to", msToTimecode(endMs),
            "-c", "copy",
            output
        )
    }

    /**
     * Builds an FFmpeg command to convert video format.
     *
     * @param input path to the source video file
     * @param output path for the converted video file
     * @return FFmpeg CLI arguments
     */
    fun convertFormat(input: String, output: String): Array<String> {
        return arrayOf(
            "-y",
            "-i", input,
            "-c:v", "libx264",
            "-c:a", "aac",
            output
        )
    }

    /**
     * Builds an FFmpeg command to merge multiple videos.
     *
     * Uses concat demuxer — all inputs must have same codec parameters.
     *
     * @param inputs list of input video file paths
     * @param output path for the merged video file
     * @return FFmpeg CLI arguments (concat list file must be created by caller)
     */
    fun mergeVideos(inputs: List<String>, output: String): Array<String> {
        // Caller must create a concat list file; this returns the command to use it.
        // Format of list file: file 'path1'\nfile 'path2'\n...
        return arrayOf(
            "-y",
            "-f", "concat",
            "-safe", "0",
            "-i", "concat_list.txt",
            "-c", "copy",
            output
        )
    }

    /**
     * Builds an FFmpeg command to extract audio from video.
     *
     * @param input path to the source video file
     * @param output path for the extracted audio file (e.g., .mp3, .aac)
     * @return FFmpeg CLI arguments
     */
    fun extractAudio(input: String, output: String): Array<String> {
        return arrayOf(
            "-y",
            "-i", input,
            "-vn",
            "-c:a", "aac",
            output
        )
    }

    /**
     * Converts milliseconds to FFmpeg timecode format (HH:MM:SS.mmm).
     */
    private fun msToTimecode(ms: Long): String {
        val totalSeconds = ms / 1000
        val hours = totalSeconds / 3600
        val minutes = (totalSeconds % 3600) / 60
        val seconds = totalSeconds % 60
        val millis = ms % 1000
        return String.format("%02d:%02d:%02d.%03d", hours, minutes, seconds, millis)
    }
}
